import { test, expect } from '@playwright/test';

test.describe('Async State Preservation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://example.com');
  });

  test('should preserve async state after navigation', async ({ page }) => {
    await page.getByRole('button', { name: 'Load Data' }).click();
    await expect(page.getByText('Data Loaded')).toBeVisible();

    await page.getByRole('link', { name: 'Navigate to Another Page' }).click();
    await expect(page.getByText('Another Page')).toBeVisible();

    await page.goBack();
    await expect(page.getByText('Data Loaded')).toBeVisible();
  });

  test('should maintain state when refreshing the page', async ({ page }) => {
    await page.getByRole('button', { name: 'Load Data' }).click();
    await expect(page.getByText('Data Loaded')).toBeVisible();

    await page.reload();
    await expect(page.getByText('Data Loaded')).toBeVisible();
  });
});
